/* ON Mission 16.7.0 — Canonical Market Factory. Market launch work is governed in one workspace. */
import {renderMarketFactory} from './market-factory.js?v=16.10.97';
const SECTOR_LABELS={logistics:'Logistics',cleaning:'Cleaning',security:'Security',general:'General Operations'};
const JOURNEY=[['prepare','Prepare Data'],['configure','Configure'],['compose','Compose'],['validate','Validate'],['test','Test'],['authorize','Authorize'],['publish','Publish'],['verify','Verify']];
const stageForNext=k=>({scope:'prepare',country:'prepare',foundation:'prepare',sectors:'prepare',evidence:'prepare',definitions:'configure',configuration:'configure',lifecycle:'configure',validate:'validate',authorize:'authorize',publish:'publish',verify:'verify',history:'verify'})[String(k||'prepare').toLowerCase()]||'prepare';
const DEFAULT_RETENTION={operational_communications:365,mission_execution:3650,security_audit:2555,account_management:3650,billing:2555};
const safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arr=v=>Array.isArray(v)?v:[];
const escJson=v=>safe(JSON.stringify(v??{},null,2));
const pretty=v=>JSON.stringify(v??{},null,2);
const statusClass=s=>['active','validated','authorized','published','verified','live','compiled','ready','completed','configured'].includes(String(s||'').toLowerCase())?'ok':['blocked','failed','retired','unavailable'].includes(String(s||'').toLowerCase())?'bad':'warn';
const present=s=>`<span class="pill ${statusClass(s)}">${safe(String(s||'UNKNOWN').toUpperCase())}</span>`;
const labelSector=s=>SECTOR_LABELS[String(s||'').toLowerCase()]||String(s||'').replaceAll('_',' ');

export async function renderLegacyProductPublisher({api,esc,state,ensureStepUp,show}){
  const box=document.querySelector('#view-product-publisher');if(!box)return;
  box.innerHTML='<div class="empty">Loading the Product Factory…</div>';
  try{
    const launchId=state.publisher?.launchId||null;
    const selectedCatalog=state.dataCatalogSelection||null;
    const selectedCountry=selectedCatalog?.type==='product_country'?(selectedCatalog.record?.code||''):'';
    const countryCode=state.publisher?.countryCode||selectedCountry||'';
    const workspace=await loadWorkspace(api,launchId,countryCode);
    state.publisher={launchId:workspace.launch?.id||launchId||null,countryCode:workspace.launch?.country_code||countryCode};
    render(box,workspace,state);
    if(selectedCatalog){const banner=box.querySelector('#publisherCatalogContext');if(banner)banner.scrollIntoView({block:'nearest'});}
    box.querySelector('#refreshPublisherProjection')?.addEventListener('click',()=>renderProductPublisher({api,esc,state,ensureStepUp,show}));
    bind(box,{api,state,ensureStepUp,show,refresh:async(next={})=>{state.publisher={...(state.publisher||{}),...next};await renderProductPublisher({api,esc,state,ensureStepUp,show});}});
  }catch(error){
    box.innerHTML=`<section class="card section error-state"><div class="eyebrow">SUPER ADMIN · PRODUCT FACTORY</div><h2>Product Factory unavailable</h2><p class="sub">No product state was changed. This is a service failure, not an empty product.</p><div class="notice">${safe(error?.message||'Product Factory is unavailable.')}</div><div class="actions"><button class="btn primary" id="retryPublisher">RETRY</button><button class="btn muted" id="publisherCommand">COMMAND CENTER</button></div></section>`;
    box.querySelector('#retryPublisher')?.addEventListener('click',()=>renderProductPublisher({api,esc,state,ensureStepUp,show}));
    box.querySelector('#publisherCommand')?.addEventListener('click',()=>show('overview'));
  }
}
async function loadWorkspace(api,launchId,countryCode){
  const q=new URLSearchParams();if(launchId)q.set('launchId',String(launchId));else if(countryCode)q.set('country',countryCode);
  const d=await api(`/api/platform/admin/product-publisher/workspace${q.toString()?`?${q}`:''}`);return d.workspace||{};
}
function progress(w){if(!w.launch)return 0;const i=JOURNEY.findIndex(x=>x[0]===stageForNext(w.next?.key));return Math.max(0,Math.min(100,Math.round((i/7)*100)));}
function stepState(key,w){if(!w.launch)return {class:key==='scope'?'current':'',detail:key==='scope'?'Start here':'Waiting'};const i=JOURNEY.findIndex(x=>x[0]===key),n=JOURNEY.findIndex(x=>x[0]===stageForNext(w.next?.key));if(n<0)return {class:'',detail:'View'};if(i<n)return {class:'done',detail:'Complete'};if(i===n)return {class:'current',detail:w.next?.message||'Next action'};if(key==='verify'&&w.launch.active)return {class:'current',detail:'Run live verification'};return {class:'',detail:'Pending'};}

function renderDiagnostics(diagnostics){
 const panels=Object.values(diagnostics?.panels||{});
 if(!panels.length)return '';
 return `<section class="card section publisher-diagnostics"><div class="section-head"><div><span class="eyebrow">SYSTEM READINESS</span><h2>Some publisher data is unavailable</h2><p class="sub">No product state was inferred from failed reads. Publishing remains governed and blocked where required.</p></div><span class="pill bad">ATTENTION</span></div><div class="checks">${panels.map(x=>`<article class="check"><b>${safe(x.panel||'publisher')}</b><div class="mini">${safe(x.code||'PUBLISHER_PANEL_READ_FAILED')}</div><p class="sub">${safe(x.message||'This panel is temporarily unavailable.')}</p></article>`).join('')}</div></section>`;
}

function humanFactoryWork(w){
  const launch=w.launch||null, next=w.next||{}, summary=w.summary||{};
  const blockers=Number(summary.remaining||0);
  const state=String(launch?.status||'not started').replaceAll('_',' ');
  const message=next.message||((blockers>0)?`Complete ${blockers} required preparation item${blockers===1?'':'s'}.`:'Review the current release state and continue the governed journey.');
  const action=next.key||'prepare';
  return `<section class="product-factory-human-work"><div><span class="eyebrow">PRODUCT WORK</span><h2>One next decision</h2><p>${safe(message)}</p></div><div class="product-factory-human-work-meta"><span class="pill ${summary.ready?'ok':'warn'}">${safe(state.toUpperCase())}</span><span class="mini">NEXT · ${safe(String(action).replaceAll('_',' ').toUpperCase())}</span><span class="mini">${blockers} remaining</span></div></section>`;
}

function render(box,w,state){
  const launch=w.launch, catalogSelection=state.dataCatalogSelection||null,bp=w.blueprint,foundation=w.foundation||{},prep=w.preparation||{},defs=arr(w.definitions),configs=arr(w.configurations),life=arr(w.lifecycleDefinitions),read=w.readiness||{},next=w.next||{},countries=arr(w.countries),sectors=arr(w.sectors).length?arr(w.sectors):arr(launch?.eligibility?.sectors);
  const projectionWarnings=arr(w.projectionWarnings);
  box.innerHTML=`<div class="publisher-console">
    ${projectionWarnings.length?`<section class="card section workspace-data-warning publisher-projection-warning"><div><b>Canonical product state was saved, but some projections need refresh.</b><small>${projectionWarnings.map(x=>safe(x.message||x.code||'Projection refresh required.')).join(' · ')}</small></div><button class="btn muted" type="button" id="refreshPublisherProjection">REFRESH PROJECTIONS</button></section>`:''}
    ${renderDiagnostics(w.diagnostics)}
    ${catalogSelection?`<section class="card section" id="publisherCatalogContext"><div class="section-head"><div><span class="eyebrow">DATA CATALOG → PRODUCT FACTORY</span><h2>Selected canonical data</h2><p class="sub">${safe(catalogSelection.record?.name||catalogSelection.record?.label||catalogSelection.record?.code||catalogSelection.type)} · ${safe(catalogSelection.type)} is active Product Factory context. The canonical record remains owned by its authority.</p></div><button class="btn muted" id="clearCatalogContext">CLEAR CONTEXT</button></div></section>`:''}
    ${factoryFlow(w)}
    ${humanFactoryWork(w)}
    <header class="publisher-console-head">
      <div><div class="eyebrow">SUPER ADMIN · CANONICAL PRODUCT PUBLISHER</div><h1 class="title">One workspace to build and publish a country product</h1><p class="sub">Everything required for a country product lives here: country policy, sectors, content, evidence, definitions, configuration, lifecycle, validation, publishing and live verification. There is no second product-building workspace.</p></div>
      <div class="publisher-command-status"><span class="eyebrow">RELEASE STATE</span>${launch?present(launch.active?'active':launch.status):'<span class="pill warn">NOT STARTED</span>'}<div class="mini">${launch?`${safe(launch.country_name||launch.country_code)} · v${safe(launch.version)} · launch #${safe(launch.id)}`:'No launch version selected'}</div></div>
    </header>
    <section class="publisher-scope-card">
      <div class="section-head"><div><span class="eyebrow">STEP 1 · PREPARE DATA</span><h2>Prepare the Product Country</h2><p class="sub">Product Factory starts with a deliberately created Product Country. Registration countries are a separate catalog and never appear here.</p></div>${launch?present(launch.active?'live version':'draft workspace'):''}</div>
      <div class="publisher-scope-grid">
        <label class="field"><span>Country</span><select id="publisherCountry" class="input">${countries.map(c=>`<option value="${safe(c.code)}" data-active="${Number(c.active)===1?'1':'0'}" ${String(c.code)===String(launch?.country_code||stateCountry(w))?'selected':''}>${safe(c.name)} (${safe(c.code)}) · ${Number(c.active)===1?'ACTIVE':'INACTIVE'}</option>`).join('')}</select></label>
        <label class="field"><span>Product name</span><input id="publisherProductName" class="input" value="${safe(launch?.manifest?.labels?.productName||bp?.contents?.find(x=>x.content_key==='product-name')?.body||bp?.name||'')}" placeholder="e.g. ON Mission Germany"></label>
        <label class="field"><span>Primary language</span><select id="publisherLanguage" class="input">${(bp?.languages||[{language_code:bp?.default_language_code||'en',language_name:bp?.default_language_code||'English',is_primary:true}]).map(x=>`<option value="${safe(x.language_code)}" ${x.is_primary?'selected':''}>${safe(x.language_name||x.language_code)}</option>`).join('')}</select></label>
        <label class="field"><span>Launch message</span><input id="publisherLaunchMessage" class="input" value="${safe(launch?.manifest?.launchMessage||'ON Mission is available for this country.')}" placeholder="Visible product availability message"></label>
      </div>
      <div class="publisher-sector-picker"><div class="section-head"><div><span class="eyebrow">SECTORS IN THIS RELEASE</span><h3>Enable the operational sectors</h3></div><span class="mini">${sectors.length} selected</span></div><div class="publisher-chip-row">${['logistics','cleaning','security','general'].map(s=>`<label class="publisher-chip"><input type="checkbox" value="${s}" data-sector-checkbox ${sectors.includes(s)?'checked':''}><span>${SECTOR_LABELS[s]}</span></label>`).join('')}</div></div>
      <div class="actions"><button class="btn primary" id="publisherStart">${launch?'SAVE SCOPE':'START PRODUCT'}</button>${launch?'<button class="btn muted" id="publisherRefresh">REFRESH</button>':''}<span id="publisherScopeMsg" class="mini"></span></div>
      <div class="notice">Need another Product Country? Use <b>Data Entry → Product Country</b>. Product Factory never creates reusable market data.</div>
    </section>
    <section class="publisher-journey-wrap"><div class="publisher-progress"><div style="width:${progress(w)}%"></div></div><div class="publisher-progress-caption"><span>${safe(next.label||'Start product')}</span><strong>${progress(w)}%</strong></div><div class="publisher-journey publisher-journey-10">${JOURNEY.map(([key,label])=>{const st=stepState(key,w);return `<article class="publisher-step ${st.class}"><div class="publisher-step-index">•</div><div><b>${label}</b><span>${safe(st.detail)}</span></div></article>`}).join('')}</div></section>
    ${launch?renderWorkspace(w,state):`<section class="card section publisher-empty-start"><div class="publisher-empty-icon">•</div><div><span class="eyebrow">START HERE</span><h2>Build a product like publishing a website</h2><p class="sub">Create or choose a Product Country, then choose sectors, enter a product name, and start. Nothing is published at this step. The publisher creates only governed draft records until validation and publication.</p><div class="notice"><b>Release rule:</b> no publish button can succeed until country foundation, definitions, lifecycles, runtime configuration and preparation are all valid for this exact launch version.</div></div></section>`}
  </div>`;
}
function factoryFlow(w){
 const l=w.launch, state=String(w.releaseLifecycle?.state||l?.status||'draft').toLowerCase();
 const stages=[['prepare','PREPARE DATA','Data Catalog · Countries · Sectors · Policies · Reference data'],['configure','CONFIGURE','Product definition · Features · Rules · Pricing · Eligibility · UX'],['compose','COMPOSE','Country Blueprint · Components · Dependencies · Operational pieces'],['validate','VALIDATE','Completeness · Dependencies · Contract · Security'],['test','TEST','Test Lab · Runtime checks · User journeys · Recovery'],['authorize','AUTHORIZE','Release approval · Step-up · Immutable snapshot'],['publish','PUBLISH','Product version · Release · Contract hash'],['verify','VERIFY','Production checks · Product health · Operational proof']];
 const next=stageForNext(w.next?.key||'prepare');
 return `<section class="card section product-factory-hero">
   <div class="product-factory-hero-main"><span class="eyebrow">SUPER ADMIN · PRODUCT FACTORY</span><h2>${safe(l?`${l.country_name||l.country_code} · v${l.version}`:'Build a product from one place')}</h2><p class="sub">Prepare reusable data, configure the product, compose the release, prove readiness, test it, authorize it, publish it and verify the live result — without leaving this workspace.</p></div>
   <div class="product-factory-hero-side"><span class="eyebrow">CURRENT STATE</span>${present(state)}<strong>${safe(w.next?.label||'Start product')}</strong><span class="mini">${safe(w.next?.message||'Create the first governed product draft.')}</span></div>
   <div class="product-factory-stepper">${stages.map((x,i)=>`<button type="button" class="product-factory-step ${next===x[0]?'current':''} ${i<stages.findIndex(y=>y[0]===next)?'done':''}" data-factory-stage="${x[0]}"><span>${i+1}</span><b>${x[1]}</b><small>${x[2]}</small></button>`).join('')}</div>
 </section>`;
}
function dependencyImpactSection(impact,graph){if(!impact)return `<section class="card section publisher-panel publisher-impact-panel"><div class="section-head"><div><span class="eyebrow">DEPENDENCY IMPACT</span><h2>Impact graph</h2><p class="sub">The canonical dependency graph is available, but the impact projection could not be loaded.</p></div><span class="pill warn">UNAVAILABLE</span></div></section>`;const r=impact.relations||{};const count=(k)=>arr(r[k]).length;const list=(k)=>arr(r[k]).map(e=>`<li><span>${safe(e.to?.label||e.from?.label||'—')}</span><small>${safe(e.relation)}</small></li>`).join('')||'<li class="empty">None declared</li>';return `<section class="card section publisher-panel publisher-impact-panel"><div class="section-head"><div><span class="eyebrow">READINESS ENGINE · DEPENDENCY IMPACT</span><h2>What changes if this product dependency changes?</h2><p class="sub">Clicking a dependency can use the same projection to explain what depends on it, what it blocks, what it affects, what verifies it and the rollback impact.</p></div><span class="pill ${Number(graph?.summary?.blockedNodes||0)?'bad':'ok'}">${Number(graph?.summary?.blockedNodes||0)?'BLOCKED':'CONNECTED'}</span></div><div class="publisher-impact-summary"><div><span>AFFECTED COUNTRIES</span><b>${safe(arr(impact.impact?.countries).length)}</b><small>${safe(arr(impact.impact?.countries).join(' · ')||'None')}</small></div><div><span>AFFECTED JOURNEYS</span><b>${safe(arr(impact.impact?.journeys).length)}</b><small>${safe(arr(impact.impact?.journeys).join(' · ')||'None')}</small></div><div><span>AFFECTED USERS</span><b>${safe(arr(impact.impact?.users).length)}</b><small>${safe(arr(impact.impact?.users).join(' · ')||'None')}</small></div><div><span>CONNECTED NODES</span><b>${safe(arr(impact.connectedNodes).length)}</b><small>Canonical graph projection</small></div></div><div class="publisher-impact-grid">${[['DEPENDS ON','dependsOn'],['USED BY','usedBy'],['BLOCKS','blocks'],['AFFECTS','affects'],['ENABLES','enables'],['VERIFIED BY','verifiedBy']].map(([label,key])=>`<article><div class="section-head"><b>${label}</b><span class="pill ${count(key)?'warn':'ok'}">${count(key)}</span></div><ul>${list(key)}</ul></article>`).join('')}</div><details class="publisher-advanced"><summary>ROLLBACK IMPACT</summary><div class="publisher-list">${arr(impact.rollbackImpact).map(x=>`<div class="publisher-list-row"><div><b>${safe(x.target)}</b><div class="mini">${safe(x.relation)}</div></div><span class="mini">${safe(x.path)}</span></div>`).join('')||'<div class="empty">No explicit rollback paths are declared for this node.</div>'}</div></details><div class="mini" style="margin-top:10px">${safe(impact.note||'Computed from the canonical dependency graph.')}</div></section>`;}

function stateCountry(w){return w.countries?.find(c=>Number(c.active)===1)?.code||w.countries?.[0]?.code||'';}

function renderWorkspace(w,state){
  const launch=w.launch,bp=w.blueprint||{},foundation=w.foundation||{},prep=w.preparation||{},defs=arr(w.definitions),configs=arr(w.configurations),life=arr(w.lifecycleDefinitions);
  const required=new Set(arr(launch?.manifest?.requiredConfigurations));
  const stage=(key,title,eyebrow,description,body,open=false)=>`<details class="product-factory-stage-panel" data-factory-panel="${key}" ${open?'open':''}><summary><span class="product-factory-stage-summary-index">${['prepare','configure','compose','validate','test','authorize','publish','verify'].indexOf(key)+1}</span><span><b>${title}</b><small>${description}</small></span><span class="product-factory-stage-summary-action">${open?'OPEN':'VIEW'}</span></summary><div class="product-factory-stage-body"><div class="product-factory-stage-head"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2><p class="sub">${description}</p></div><button class="btn muted" type="button" data-factory-focus="${key}">FOCUS</button></div>${body}</div></details>`;
  return `<section class="product-factory-workspace">
    ${quickCatalogSection(w,state)}
    ${stage('prepare','1. Prepare Data','DATA FOUNDATION','Prepare the reusable country, sector, policy, provider, language and reference-data foundation before configuring the product.',`${scopeSummary(w)}${foundationSection(launch,foundation)}${blueprintSection(bp)}${preparationSection(prep)}`,true)}
    ${stage('configure','2. Configure','PRODUCT CONFIGURATION','Configure the product in business language. Advanced technical representation stays behind expandable controls.',`${definitionSection(defs)}${configSection(configs,required,w.semanticConfiguration)}${lifecycleSection(life,arr(w.sectors))}`)}
    ${stage('compose','3. Compose','PRODUCT COMPOSITION','Assemble the selected country blueprint, product definitions, canonical dependencies and operational pieces into one release composition.',`${governanceSection(w.controlPlaneGovernance)}${dependencyImpactSection(w.dependencyImpact,w.dependencyGraph)}${productContractSection(w.productContract)}`)}
    ${stage('validate','4. Validate','READINESS GATE','The server-side readiness and validation authorities decide whether this exact version can proceed.',`${readinessSection(w)}`)}
    ${stage('test','5. Test','TEST LAB','Prove the composed product before publication with controlled checks, runtime scenarios and recovery paths.',`${testLabSection(w.testLab)}${testScenarioSection(w.testScenario,state,w)}`)}
    ${stage('authorize','6. Authorize','GOVERNED APPROVAL','Review the immutable contract, dependency snapshot, authorization state and rollback path before publish.',`${releaseLifecycleSection(w)}${authorizationSummary(w)}`)}
    ${stage('publish','7. Publish','RELEASE','Publish only the authorized immutable version through the existing canonical release authority.',`${releaseLifecycleSection(w)}${readinessSection(w)}`)}
    ${stage('verify','8. Verify','LIVE PROOF','Verify the live product using the existing Product Verification Engine and then monitor the product operationally.',`${testScenarioSection(w.testScenario,state,w)}${releaseLifecycleSection(w)}${contractSection(w)}`)}
  </section>`;
}
function scopeSummary(w){const l=w.launch||{},bp=w.blueprint||{},sectors=arr(w.sectors);return `<section class="product-factory-summary-grid"><article><span>PRODUCT</span><b>${safe(l.manifest?.labels?.productName||bp.name||'Not created')}</b><small>${l?`v${safe(l.version)} · ${safe(l.status)}`:'Create the draft first'}</small></article><article><span>COUNTRY</span><b>${safe(l.country_name||l.country_code||'—')}</b><small>${Number(l.country_catalog_active)===1?'ACTIVE':'ACTIVATE BEFORE BUILD'}</small></article><article><span>SECTORS</span><b>${sectors.length}</b><small>${safe(sectors.map(labelSector).join(' · ')||'Add a sector')}</small></article><article><span>BLUEPRINT</span><b>${safe(bp.name||'Not ready')}</b><small>${safe(bp.status||'Prepare country foundation')}</small></article></section>`;}
function quickCatalogSection(w,state){const bp=w.blueprint||{}, sectors=arr(bp.sectors),contents=arr(bp.contents),countries=arr(w.countries),plans=arr(state?.data?.plans),providers=arr(w.foundation?.providers),languages=arr(bp.languages);return `<section class="card section product-factory-catalog"><div class="section-head"><div><span class="eyebrow">PRODUCT FACTORY · REUSABLE DATA</span><h2>Prepare data through Data Entry</h2><p class="sub">Product Factory composes canonical data. It does not create reusable platform data. Use Data Entry for creation, then return here to compose the result.</p></div><div class="actions"><button class="btn muted" data-factory-open="data-catalog">OPEN DATA CATALOG</button><button class="btn muted" data-factory-open="data-studio">OPEN DATA STUDIO</button><button class="btn primary" data-factory-entry="product_country">OPEN DATA ENTRY</button></div></div><div class="product-factory-catalog-grid">${catalogCard('Countries',countries.length,'Product Country catalog','countries',`<span>${countries.filter(x=>Number(x.active)===1).length} active</span>`)}${catalogCard('Sectors',sectors.length,'Reusable operational sectors','data-entry',`<button class="btn muted" data-factory-entry="sector">OPEN DATA ENTRY</button>`)}${catalogCard('Policies',Number((w.foundation?.jurisdiction?.code?1:0))+arr(w.foundation?.retention).length,'Country governance','policies','<span>Canonical policy owners</span>')}${catalogCard('Reference data',contents.length,'Reusable product content','data-entry',`<button class="btn muted" data-factory-entry="page">OPEN DATA ENTRY</button>`)}${catalogCard('Plans',plans.length,'Commercial catalog','subscriptions','<span>Open commercial plans</span>')}${catalogCard('Roles',Number(w.semanticConfiguration?.rolePolicy?.roles?.length||0),'Role/action policy','roles','<span>Inspect canonical roles</span>')}${catalogCard('Providers',providers.length,'Approved infrastructure','providers','<span>Inspect provider governance</span>')}${catalogCard('Languages',languages.length,'Reusable language data','data-entry',`<button class="btn muted" data-factory-entry="language">OPEN DATA ENTRY</button>`)}</div><div class="notice">Creation lives in Data Entry. This workspace only composes and validates the canonical result.</div></section>`;}
function catalogCard(title,count,sub,key,action){return `<article class="product-factory-catalog-card"><div><span>${safe(title)}</span><b>${safe(count)}</b><small>${safe(sub)}</small></div><div class="actions">${action.includes('button')?action:`<button class="btn muted" data-factory-open="${safe(key)}">OPEN</button>`}</div></article>`;}
function authorizationSummary(w){const r=w.releaseLifecycle||{};return `<section class="product-factory-approval-grid"><article><span>CONTRACT HASH</span><b>${safe((r.contract_hash||w.productContract?.contractHash||'PENDING').slice(0,18))}${r.contract_hash||w.productContract?.contractHash?'…':''}</b><small>Immutable release composition</small></article><article><span>DEPENDENCY SNAPSHOT</span><b>${r.dependency_snapshot_json&&r.dependency_snapshot_json!=='{}'?'CAPTURED':'PENDING'}</b><small>Release dependency state</small></article><article><span>ROLLBACK</span><b>${r.rollback_path_json&&r.rollback_path_json!=='{}'?'DEFINED':'PENDING'}</b><small>Governed recovery path</small></article></section>`;}



function testLabSection(t){
 if(!t)return `<section class="card section publisher-panel"><div class="section-head"><div><span class="eyebrow">TEST LAB</span><h2>Pre-publication contract tests</h2><p class="sub">The Test Lab is read-only and proves that the composed product contract is coherent before publication.</p></div><span class="pill warn">NOT RUN</span></div></section>`;
 const s=t.summary||{};return `<section class="card section publisher-panel publisher-test-lab"><div class="section-head"><div><span class="eyebrow">TEST LAB</span><h2>Pre-publication contract tests</h2><p class="sub">Configuration readiness is tested separately from live-user verification. The live Product Verification Engine remains the post-publication proof.</p></div><span class="pill ${s.ready?'ok':'bad'}">${safe(s.score||0)}% · ${safe(s.ready?'READY':'BLOCKED')}</span></div><div class="publisher-stat-row"><div class="publisher-mini-stat"><span>Checks</span><strong>${safe(s.total||0)}</strong></div><div class="publisher-mini-stat"><span>Passed</span><strong>${safe(s.passed||0)}</strong></div><div class="publisher-mini-stat"><span>Blocked</span><strong>${safe(s.blocked||0)}</strong></div></div><div class="publisher-governance-list">${arr(t.checks).map(c=>`<article class="publisher-governance-row"><div><b>${safe(c.label)}</b><div class="mini">${safe(c.category)}</div></div>${present(c.status)}<div class="mini">${safe(c.detail)}</div></article>`).join('')}</div><div class="publisher-governance-list">${arr(t.journeys).map(j=>`<article class="publisher-governance-row"><div><b>${safe(j.label)}</b><div class="mini">Journey contract · ${safe(j.code)}</div></div><span class="pill ok">DEFINED</span><div class="mini">${safe(arr(j.steps).length)} canonical steps</div></article>`).join('')}</div>${arr(t.blocked).map(b=>`<div class="publisher-blocker"><span class="publisher-dot"></span><div><b>${safe(b.code)}</b><div class="mini">${safe(b.message)}</div></div></div>`).join('')}</section>`;
}


function testScenarioSection(scenario,state,w){
 const launch=w.launch;if(!launch)return '';
 const phases=arr(scenario?.steps);const status=String(scenario?.status||'NOT PREPARED').toUpperCase();
 const companies=arr(state?.data?.companies).filter(c=>String(c.country_code||'').toUpperCase()===String(launch.country_code||'').toUpperCase()&&['VERIFIED','ACTIVE'].includes(String(c.management_status||c.status||'').toUpperCase()));
 const companyOptions=companies.map(c=>`<option value="${safe(c.id||c.company_id)}" ${Number(c.id||c.company_id)===Number(scenario?.companyId)?'selected':''}>${safe(c.legal_name||c.name||`Organization #${c.id||c.company_id}`)} · ${safe(c.sector_code||'general')}</option>`).join('');
 const phaseClass=x=>String(x.status)==='ready'||String(x.status)==='completed'?'ok':String(x.status)==='blocked'?'bad':'warn';
 return `<section class="card section publisher-panel publisher-test-scenario-panel"><div class="section-head"><div><span class="eyebrow">TEST LAB · SCENARIO PREPARATION</span><h2>Prepare the exact controlled proof path</h2><p class="sub">Preparation creates a governed scenario plan only. It does not execute user behavior. The Product Verification Engine remains the sole owner of live verification execution.</p></div><span class="pill ${statusClass(status.toLowerCase())}">${safe(status)}</span></div><div class="publisher-stat-row"><div class="publisher-mini-stat"><span>Launch version</span><strong>${safe(launch.version||'—')}</strong></div><div class="publisher-mini-stat"><span>Phases</span><strong>${safe(phases.length||8)}</strong></div><div class="publisher-mini-stat"><span>Target tenant</span><strong>${scenario?.companyId?`#${safe(scenario.companyId)}`:'Required'}</strong></div><div class="publisher-mini-stat"><span>Scenario</span><strong>${scenario?.id?`#${safe(scenario.id)}`:'Not prepared'}</strong></div></div><div class="form-grid publisher-test-scenario-target"><label class="field"><span>Representative tenant</span><select id="publisherScenarioCompany" class="input"><option value="">Select a verified/active tenant</option>${companyOptions}</select></label><label class="field"><span>Representative mission <span class="mini">optional until mission phase</span></span><input id="publisherScenarioMission" class="input" type="number" min="1" value="${safe(scenario?.missionId||'')}" placeholder="Mission ID"></label><div class="actions full"><button class="btn primary" id="publisherPrepareScenario">${scenario?'REFRESH CONTROLLED SCENARIO':'PREPARE CONTROLLED SCENARIO'}</button><span id="publisherScenarioMsg" class="mini"></span></div></div><div class="publisher-scenario-path">${[['REGISTRATION','registration'],['TENANT','tenant'],['EXECUTOR','executor'],['MISSION','mission'],['ASSIGNMENT','assignment'],['EXECUTION','execution'],['EVIDENCE','evidence'],['COMPLETION','completion']].map(([label,code])=>`<article class="publisher-scenario-node"><span>${label}</span><b>${phases.find(x=>x.phase_code===code)?.status?.toUpperCase()||'WAITING'}</b></article>`).join('')}</div><div class="publisher-governance-list">${phases.map(x=>`<article class="publisher-governance-row"><div><b>${safe(x.label)}</b><div class="mini">${safe(arr(x.journeys).join(' · '))}</div></div><span class="pill ${phaseClass(x)}">${safe(String(x.status||'READY').toUpperCase())}</span><div class="mini">${safe(x.evidence?.message||x.preconditions?.goal||'Controlled scenario phase')}</div></article>`).join('')||'<div class="empty">No scenario prepared yet.</div>'}</div>${arr(scenario?.scenario?.blockers).map(b=>`<div class="publisher-blocker"><span class="publisher-dot"></span><div><b>${safe(b.code)}</b><div class="mini">${safe(b.message)}</div><div class="mini">Next action: ${safe(b.nextAction||'Resolve blocker')}</div></div></div>`).join('')}<details class="publisher-advanced"><summary>ADVANCED · SCENARIO CONTRACT</summary><pre class="code-input">${escJson(scenario?.scenario||{})}</pre></details></section>`;
}


function productContractSection(c){
 if(!c?.contract)return `<section class="card section publisher-panel"><div class="section-head"><div><span class="eyebrow">PRODUCT CONTRACT</span><h2>Immutable release composition</h2><p class="sub">The exact country + product + version contract will be compiled once the launch exists.</p></div><span class="pill warn">NOT COMPILED</span></div></section>`;
 const x=c.contract||{};const i=x.identity||{},comp=x.composition||{},f=x.countryFoundation||{},prep=x.preparation||{},rt=x.runtimeConfiguration||{},d=arr(x.definitions),lc=x.lifecycle||{},dep=x.dependencies||{},g=x.governance||{};
 return `<section class="card section publisher-panel publisher-contract-panel"><div class="section-head"><div><span class="eyebrow">PRODUCT CONTRACT</span><h2>Immutable release composition</h2><p class="sub">This is a computed snapshot of canonical authorities for the exact launch version. It is not a second source of truth.</p></div><span class="pill ok">COMPILED</span></div><div class="publisher-stat-row"><div class="publisher-mini-stat"><span>Country</span><strong>${safe(i.countryCode||'—')}</strong></div><div class="publisher-mini-stat"><span>Version</span><strong>${safe(i.version||'—')}</strong></div><div class="publisher-mini-stat"><span>Sectors</span><strong>${safe(arr(comp.sectors).length)}</strong></div><div class="publisher-mini-stat"><span>Contract hash</span><strong title="${safe(c.contractHash||'')}">${safe((c.contractHash||'').slice(0,12))}…</strong></div></div><div class="publisher-governance-list"><article class="publisher-governance-row"><div><b>Country foundation</b><div class="mini">Jurisdiction · residency · billing · retention · communication · storage</div></div>${present(f.ready?'READY':'BLOCKED')}<div class="mini">${safe(f.ready?'Complete':'Foundation blockers remain')}</div></article><article class="publisher-governance-row"><div><b>Preparation &amp; evidence</b><div class="mini">Required release preparation</div></div>${present(prep.summary?.ready?'READY':'BLOCKED')}<div class="mini">${safe(prep.summary?.completed||0)}/${safe(prep.summary?.total||0)} complete</div></article><article class="publisher-governance-row"><div><b>Product definitions</b><div class="mini">One definition per declared sector</div></div>${present(d.length===arr(comp.sectors).length&&d.every(x=>['compiled','validated','active'].includes(String(x.status)))?'READY':'BLOCKED')}<div class="mini">${safe(d.length)} definitions</div></article><article class="publisher-governance-row"><div><b>Runtime configuration</b><div class="mini">Required active versions</div></div>${present(!arr(rt.missing).length?'READY':'BLOCKED')}<div class="mini">${safe(arr(rt.active).length)}/${safe(arr(rt.required).length)} active</div></article><article class="publisher-governance-row"><div><b>Lifecycle</b><div class="mini">Canonical sector lifecycle contracts</div></div>${present(lc.valid?'READY':'BLOCKED')}<div class="mini">${safe(arr(lc.sectors).length)} sector lifecycle(s)</div></article><article class="publisher-governance-row"><div><b>Dependency graph</b><div class="mini">Release composition graph</div></div>${present(Number(dep.blockedNodes||0)===0?'READY':'BLOCKED')}<div class="mini">${safe(dep.nodes||0)} nodes · ${safe(dep.edges||0)} edges</div></article><article class="publisher-governance-row"><div><b>Governance</b><div class="mini">Control Plane resource contracts</div></div>${present(Number(g.summary?.blocked||0)===0?'READY':'BLOCKED')}<div class="mini">${safe(g.resourceCount||0)} governed resources</div></article></div><details class="publisher-advanced"><summary>VIEW COMPILED CONTRACT JSON</summary><pre class="code-input">${escJson(x)}</pre></details></section>`;
}

function governanceSection(g){
 const resources=arr(g?.resources),summary=g?.summary||{};
 if(!resources.length)return `<section class="card section publisher-panel"><div class="section-head"><div><span class="eyebrow">CONTROL PLANE GOVERNANCE</span><h2>Governance graph</h2><p class="sub">The governance contract becomes available when a product launch exists.</p></div></div></section>`;
 const blockers=resources.flatMap(r=>arr(r.readiness?.blockers).map(b=>({...b,resource:r.resource})));
 return `<section class="card section publisher-panel publisher-governance-panel"><div class="section-head"><div><span class="eyebrow">CONTROL PLANE GOVERNANCE</span><h2>Every governed resource has a readiness contract</h2><p class="sub">Readiness, dependencies, structured blockers and verification are standardized across the Control Plane while canonical domain services remain the authorities.</p></div><span class="pill ${summary.blocked||summary.unavailable?'bad':'ok'}">${safe(summary.readyPercent??0)}% READY</span></div><div class="publisher-stat-row"><div class="publisher-mini-stat"><span>Governed resources</span><strong>${safe(summary.total||0)}</strong></div><div class="publisher-mini-stat"><span>Ready</span><strong>${safe(summary.ready||0)}</strong></div><div class="publisher-mini-stat"><span>Blocked</span><strong>${safe(summary.blocked||0)}</strong></div><div class="publisher-mini-stat"><span>Unavailable</span><strong>${safe(summary.unavailable||0)}</strong></div></div><div class="publisher-governance-list">${resources.map(r=>`<article class="publisher-governance-row"><div><b>${safe(r.resource?.label||r.resource?.key)}</b><div class="mini">${safe(r.resource?.type||'resource')} · ${safe(r.resource?.key||'')}</div></div>${present(r.readiness?.status)}<div class="mini">${safe((r.readiness?.blockers||[])[0]?.message||`${r.dependencies?.length||0} dependencies`)}</div></article>`).join('')}</div>${blockers.slice(0,12).map(b=>`<div class="publisher-blocker"><span class="publisher-dot"></span><div><b>${safe(b.code)}</b><div class="mini">${safe(b.resource?.label||b.resource?.key||'Resource')} · ${safe(b.message)}</div>${b.nextAction?`<div class="mini">Next action: ${safe(b.nextAction)}</div>`:''}</div></div>`).join('')}</section>`;
}

function foundationSection(launch,f){
  const r=f.residency||{},b=f.billing||{},j=f.jurisdiction||{};const ready=f.ready;
  const ret=arr(f.retention),not=arr(f.notifications),storage=arr(f.storage),providers=arr(f.providers).filter(x=>x.provider_type==='storage');
  return `<section class="card section publisher-panel publisher-foundation-panel"><div class="section-head"><div><span class="eyebrow">COUNTRY FOUNDATION</span><h2>Country runtime foundation</h2><p class="sub">The country must have an actual jurisdiction, residency, retention, billing, communications and storage policy chain. The workspace never invents a country behind your back.</p></div>${present(ready?'ready':'blocked')}</div>
    ${ready?`<div class="publisher-stat-row"><div class="publisher-mini-stat"><span>Jurisdiction</span><strong>${safe(j.code||'—')}</strong></div><div class="publisher-mini-stat"><span>Residency</span><strong>${safe(r.primaryRegion||'—')}</strong></div><div class="publisher-mini-stat"><span>Billing</span><strong>${safe(`${b.currency||'—'} · ${b.provider_code||'—'}`)}</strong></div></div><div class="publisher-foundation-checks"><span>${ret.length} retention purposes</span><span>${not.length} notification policies</span><span>Storage: ${safe(r.primaryProvider||'—')}</span></div>`:`${foundationForm(f,launch)}`}
    ${arr(f.blockers).map(x=>`<div class="publisher-blocker"><span class="publisher-dot"></span><div><b>${safe(x.code)}</b><div class="mini">${safe(x.message)}</div></div></div>`).join('')}
  </section>`;
}
function foundationForm(f,launch){
  const j=f.jurisdiction||{},r=f.residency||{},b=f.billing||{};const currentProvider=r.primaryProvider||f.storage?.find(x=>x.code)?.code||'';const retention={};for(const x of arr(f.retention))retention[x.purpose_code]={retentionDays:x.retention_days,actionAfterExpiry:x.action_after_expiry,legalHoldAllowed:Number(x.legal_hold_allowed)===1};
  return `<div class="publisher-form-stack"><div class="notice"><b>Fill this once.</b> The Publisher writes the canonical country policy records. Existing active foundations are shown read-only; changing an active foundation requires a new governed release.</div>
    <div class="publisher-scope-grid"><label class="field"><span>Framework code</span><input id="foundationFramework" class="input" value="${safe(j.framework_code||'')}" placeholder="e.g. GDPR"></label><label class="field"><span>Jurisdiction region</span><input id="foundationRegion" class="input" value="${safe(j.region_code||'')}" placeholder="e.g. DE"></label><label class="field"><span>Primary data region</span><input id="foundationPrimaryRegion" class="input" value="${safe(r.primary_region||'')}" placeholder="e.g. Germany"></label><label class="field"><span>Storage provider</span><select id="foundationStorageProvider" class="input"><option value="">Choose a real approved provider</option>${arr(f.providers).filter(x=>x.provider_type==='storage').map(x=>`<option value="${safe(x.code)}" ${x.code===currentProvider?'selected':''}>${safe(x.name)} · ${safe(x.code)} · ${safe(x.region_code||x.country_code||'global')}</option>`).join('')}</select></label></div>
    <div class="publisher-scope-grid"><label class="field"><span>Currency</span><input id="foundationCurrency" class="input" value="${safe(b.currency||'EUR')}" maxlength="3"></label><label class="field"><span>Tax configuration</span><input id="foundationTax" class="input" value="${safe(b.tax_configuration_code||'')}" placeholder="e.g. DE_STANDARD"></label><label class="field"><span>Billing provider</span><select id="foundationBillingProvider" class="input">${arr(f.providers).filter(x=>x.provider_type==='payment').map(x=>`<option value="${safe(x.code)}" ${x.code===(b.provider_code||'stripe')?'selected':''}>${safe(x.name)} · ${safe(x.code)}</option>`).join('')}</select></label><label class="field"><span>Residency mode</span><select id="foundationResidencyMode" class="input"><option value="required" ${r.mode==='required'?'selected':''}>Required</option><option value="preferred" ${r.mode==='preferred'?'selected':''}>Preferred</option><option value="policy" ${r.mode==='policy'?'selected':''}>Policy</option></select></label></div>
    <label class="field"><span>Invoice requirements JSON</span><textarea class="input" rows="3" id="foundationInvoice">${safe(pretty(b.invoice_requirements_json?JSON.parse(b.invoice_requirements_json):{}))}</textarea></label>
    <div class="publisher-retention-grid">${['operational_communications','mission_execution','security_audit','account_management','billing'].map(p=>{const x=retention[p]||{};return `<div class="publisher-retention-card"><b>${safe(p.replaceAll('_',' '))}</b><input class="input" type="number" min="1" max="36500" data-retention-days="${p}" value="${safe(x.retentionDays??DEFAULT_RETENTION[p])}"><select class="input" data-retention-action="${p}"><option value="review" ${x.actionAfterExpiry==='review'?'selected':''}>Review</option><option value="delete" ${x.actionAfterExpiry==='delete'?'selected':''}>Delete</option><option value="anonymize" ${x.actionAfterExpiry==='anonymize'?'selected':''}>Anonymize</option><option value="restrict" ${x.actionAfterExpiry==='restrict'?'selected':''}>Restrict</option></select></div>`}).join('')}</div>
    <div class="actions"><button class="btn primary" id="saveFoundation">SAVE COUNTRY FOUNDATION</button><span class="mini">Provider selection must refer to an actually configured storage/payment provider. No fake infrastructure is created.</span></div>
  </div>`;
}
function blueprintSection(bp){return `<section class="card section publisher-panel"><div class="section-head"><div><span class="eyebrow">FOUNDATION CONTENT</span><h2>Content + legal evidence</h2><p class="sub">Edit the exact content and evidence attached to this country blueprint.</p></div>${present(bp.status||'preparing')}</div><div class="publisher-list">${arr(bp.legalRequirements).filter(x=>x.required).map(x=>`<div class="publisher-inline-editor"><div class="publisher-list-row"><div><b>${safe(x.title)}</b><div class="mini">${safe(x.requirement_key)}</div></div>${present(x.status)}</div><textarea class="input" rows="2" data-legal-note="${x.id}" placeholder="Review note / evidence source">${safe(x.source_url||'')}</textarea><button class="btn muted" data-legal-review="${x.id}" data-legal-key="${safe(x.requirement_key)}">SAVE LEGAL REVIEW</button></div>`).join('')||'<div class="empty">No required legal items have been created.</div>'}</div><div class="publisher-content-editor">${arr(bp.contents).filter(x=>x.required).map(x=>`<div class="publisher-inline-editor"><label class="field"><span>${safe(x.title)} · ${safe(x.language_code)}</span><textarea class="input" rows="3" data-content-body="${safe(x.content_key)}:${safe(x.language_code)}">${safe(x.body||'')}</textarea></label><button class="btn muted" data-content-save="${safe(x.content_key)}:${safe(x.language_code)}">SAVE CONTENT</button></div>`).join('')}</div></section>`;}
function preparationSection(p){const tasks=arr(p.tasks),research=arr(p.research);return `<section class="card section publisher-panel"><div class="section-head"><div><span class="eyebrow">PREPARATION & EVIDENCE</span><h2>Launch preparation workspace</h2><p class="sub">Every required preparation item must have a real completion state and evidence. No click-only checklist.</p></div>${present(p.summary?.ready?'ready':'preparing')}</div><div class="publisher-stat-row"><div class="publisher-mini-stat"><span>Progress</span><strong>${safe(p.summary?.progress??0)}%</strong></div><div class="publisher-mini-stat"><span>Remaining</span><strong>${safe(p.summary?.remaining??0)}</strong></div><div class="publisher-mini-stat"><span>Blocked</span><strong>${safe(p.summary?.blocked??0)}</strong></div></div><div class="publisher-task-list">${tasks.map(x=>`<article class="publisher-task-card"><div><b>${safe(x.title||x.task_key)}</b><div class="mini">${safe(x.description||x.task_key||'Required preparation')}</div></div>${present(x.status)}${x.status==='completed'?`<div class="mini">${safe(x.completion_note||'Completed')}</div>`:`<textarea class="input" rows="2" data-task-note="${x.id}" placeholder="Completion note / evidence"> </textarea><input class="input" data-task-sources="${x.id}" placeholder="Evidence URLs or references, comma separated"><button class="btn muted" data-task-complete="${x.id}">MARK COMPLETE</button>`}</article>`).join('')||'<div class="empty">No preparation tasks.</div>'}</div><div class="publisher-task-list">${research.map(x=>`<article class="publisher-task-card"><div><b>Research · ${safe(x.topic||x.research_key)}</b><div class="mini">${safe(x.description||'Country/product research')}</div></div>${present(x.status)}${x.status==='completed'?`<div class="mini">${safe(x.findings||'Completed')}</div>`:`<textarea class="input" rows="2" data-research-findings="${x.id}" placeholder="Research findings"></textarea><input class="input" data-research-sources="${x.id}" placeholder="Sources, comma separated"><button class="btn muted" data-research-complete="${x.id}">MARK RESEARCH COMPLETE</button>`}</article>`).join('')}</div></section>`;}
function definitionSection(defs){return `<section class="card section publisher-panel"><div class="section-head"><div><span class="eyebrow">PRODUCT DEFINITIONS</span><h2>Product composition</h2><p class="sub">Configure the product in business language. Canonical component JSON remains available only in Advanced.</p></div></div><div class="publisher-sector-grid">${defs.map(d=>`<article class="publisher-sector-card"><div class="section-head"><div><b>${safe(labelSector(d.sector_code))}</b><div class="mini">${safe(d.product_key)}</div></div>${present(d.status)}</div><label class="field"><span>Product name</span><input class="input" data-definition-name="${d.id}" value="${safe(d.name)}"></label><label class="field"><span>Product description</span><textarea class="input" rows="3" data-definition-description="${d.id}">${safe(d.description||'')}</textarea></label><div class="publisher-stat-row"><div class="publisher-mini-stat"><span>Components</span><strong>${safe(arr(d.components).length)}</strong></div><div class="publisher-mini-stat"><span>Compiled</span><strong>${safe(d.compiled_hash?'YES':'PENDING')}</strong></div></div><details class="publisher-advanced"><summary>ADVANCED · COMPONENT CONFIGURATION</summary><div class="notice">Components are reusable data and are created exclusively in Data Entry. Product Factory only composes the resulting canonical components.</div><button class="btn muted" data-factory-entry="component" data-definition-id="${d.id}">OPEN DATA ENTRY · COMPONENT</button></details><div class="actions"><button class="btn muted" data-definition-save="${d.id}">SAVE DEFINITION</button><button class="btn primary" data-definition-compile="${d.id}">COMPILE</button></div></article>`).join('')||'<div class="empty">No product definitions yet.</div>'}</div></section>`;}
function semanticCapabilityLabel(key){return ({organization:'Organization',people:'People',mission:'Mission',object:'Objects',resource:'Resources',communication:'Communication',evidence:'Evidence',logistics:'Logistics',relationship:'Relationships',policy:'Policy',capability:'Capability catalog'}[String(key)]||String(key||'').replaceAll('_',' '));}
function semanticActionLabel(code){return ({create_mission:'Create mission',edit_mission:'Edit mission',edit_mission_data:'Edit mission data',delete_mission:'Delete mission',assign_driver:'Assign executor',change_driver:'Change executor',share_network:'Share mission (network)',share_foryou:'Share mission (ForYou)',repost_foryou:'Republish mission (ForYou)',restart_network:'Restart network sharing',approve_foryou_request:'Approve ForYou request',decline_foryou_request:'Decline ForYou request',create_driver:'Create executor',request_foryou_mission:'Request mission (ForYou)',accept_network:'Accept network mission'}[String(code)]||String(code||'').replaceAll('_',' '));}
function semanticConfigSection(sc,configs,required){const rows=configs.filter(c=>required.has(`${c.domain_code}:${c.config_key}`));const caps=sc?.capabilities;const roles=sc?.rolePolicy;const capBasic=arr(caps?.catalog).filter(x=>!x.advanced);const capAdvanced=arr(caps?.catalog).filter(x=>x.advanced);const roleRows=arr(roles?.roles);const saveButton=(key,row,label)=>`<div class="actions"><button class="btn primary" data-semantic-save="${safe(key)}" data-active-id="${safe(row?.id||'')}" data-active-version="${safe(row?.version||'')}">${label}</button><span class="mini">Creates a new governed configuration version; the active version is never edited in place.</span></div>`;
 const capabilitiesHtml=caps?`<article class="publisher-config-card publisher-semantic-card"><div class="section-head"><div><span class="eyebrow">CAPABILITIES</span><h3>What this product can do</h3><div class="mini">${safe(caps.active?'Active version '+caps.version:'No active version')} · canonical key kept in Advanced</div></div>${present(caps.status||'missing')}</div><div class="publisher-semantic-grid">${capBasic.map(c=>`<label class="publisher-semantic-option"><input type="checkbox" data-semantic-capability="${safe(c.key)}" ${c.enabled?'checked':''}><span><b>${safe(c.label)}</b><small>${safe(c.description)}</small></span></label>`).join('')}</div><details class="publisher-advanced"><summary>ADVANCED CAPABILITIES</summary><div class="publisher-semantic-grid">${capAdvanced.map(c=>`<label class="publisher-semantic-option"><input type="checkbox" data-semantic-capability="${safe(c.key)}" ${c.enabled?'checked':''}><span><b>${safe(c.label)}</b><small>${safe(c.description)}</small></span></label>`).join('')}</div></details>${saveButton('capabilities:catalog',rows.find(x=>`${x.domain_code}:${x.config_key}`==='capabilities:catalog'),caps.active?'SAVE CAPABILITIES':'CREATE + ACTIVATE')}</article>`:'<article class="publisher-config-card"><div class="empty">Capabilities configuration is not available. Publishing remains blocked.</div></article>';
 const roleActions=arr(roles?.actionCatalog).length?arr(roles.actionCatalog):[...new Map(roleRows.flatMap(r=>arr(r.actions).map(a=>[a.code,a])).filter(([k])=>k)).values()];
 const roleHtml=roles?`<article class="publisher-config-card publisher-semantic-card"><div class="section-head"><div><span class="eyebrow">ROLE POLICY</span><h3>What each role can do</h3><div class="mini">Semantic controls map directly to the canonical action policy.</div></div>${present(roles.status||'missing')}</div><div class="publisher-role-policy">${roleRows.map(r=>`<div class="publisher-role-card"><div class="section-head"><div><b>${safe(r.label)}</b><div class="mini">${safe(r.key)}</div></div><span class="pill ok">${safe(arr(r.actions).filter(a=>a.enabled).length)} actions</span></div><div class="publisher-action-grid">${roleActions.map(a=>{const enabled=arr(r.actions).some(x=>x.code===a.code&&x.enabled);return `<label class="publisher-semantic-option"><input type="checkbox" data-semantic-role="${safe(r.key)}" data-semantic-action="${safe(a.code)}" ${enabled?'checked':''}><span><b>${safe(semanticActionLabel(a.code))}</b><small>${safe(a.code)}</small></span></label>`}).join('')}</div></div>`).join('')}</div>${saveButton('roles:action_policy',rows.find(x=>`${x.domain_code}:${x.config_key}`==='roles:action_policy'),roles.active?'SAVE ROLE POLICY':'CREATE + ACTIVATE')}</article>`:'<article class="publisher-config-card"><div class="empty">Role policy configuration is not available. Publishing remains blocked.</div></article>';
 const advanced=rows.filter(x=>x.domain_code+':'+x.config_key!=='capabilities:catalog'&&x.domain_code+':'+x.config_key!=='roles:action_policy');
 const advancedHtml=advanced.map(row=>`<article class="publisher-config-card"><div class="section-head"><div><b>${safe(row.domain_code+':'+row.config_key)}</b><div class="mini">Active version ${safe(row.version)}</div></div>${present(row.status)}</div><details class="publisher-advanced"><summary>ADVANCED · RAW CANONICAL CONFIGURATION</summary><textarea class="input code-input" rows="7" data-config-body="${safe(row.domain_code+':'+row.config_key)}">${escJson(row.payload||{})}</textarea><div class="actions"><button class="btn primary" data-config-save="${safe(row.domain_code+':'+row.config_key)}" data-active-id="${safe(row.id||'')}" data-active-version="${safe(row.version||'')}">SAVE NEW VERSION</button></div></details></article>`).join('');
 return `<section class="card section publisher-panel" id="publisherConfiguration"><div class="section-head"><div><span class="eyebrow">PRODUCT COMPOSITION · CONFIGURATION</span><h2>Configure the product in product language</h2><p class="sub">Basic mode is the Super Admin workflow. Advanced mode exposes the exact canonical representation without creating a second authority.</p></div><span class="pill ok">CANONICAL CONFIGURATION</span></div><div class="publisher-mode-switch"><button class="btn primary" type="button" data-config-mode="basic">BASIC</button><button class="btn muted" type="button" data-config-mode="advanced">ADVANCED</button><span class="mini">Switching modes changes presentation only; both views address the same governed configuration.</span></div><div class="publisher-basic-layer"><div class="publisher-basic-overview"><div><b>Basic configuration</b><span>Product name · country · language · sectors · plans · user classes · capabilities · roles · billing · storage · notifications · lifecycle · legal/content · publish settings</span></div></div><div class="publisher-list">${capabilitiesHtml}${roleHtml}</div></div><div class="publisher-advanced-layer" style="display:none"><div class="publisher-basic-overview"><div><b>Advanced configuration</b><span>canonical JSON · version IDs · policy keys · action codes · provider IDs · configuration lineage · raw contract · audit references</span></div></div><div class="publisher-list">${advancedHtml}${caps?`<article class="publisher-config-card"><div class="section-head"><div><b>capabilities:catalog</b><div class="mini">Canonical capability configuration</div></div>${present(caps.status||'missing')}</div><details class="publisher-advanced"><summary>VIEW CANONICAL JSON</summary><pre class="code-input">${escJson(caps.raw||{})}</pre></details></article>`:''}${roles?`<article class="publisher-config-card"><div class="section-head"><div><b>roles:action_policy</b><div class="mini">Canonical role/action policy</div></div>${present(roles.status||'missing')}</div><details class="publisher-advanced"><summary>VIEW CANONICAL JSON</summary><pre class="code-input">${escJson(roles.raw||{})}</pre></details></article>`:''}</div></div></section>`;}
function configSection(configs,required,semanticConfiguration){return semanticConfigSection(semanticConfiguration,configs,required);}
function lifecycleSection(life,sectors){return `<section class="card section publisher-panel"><div class="section-head"><div><span class="eyebrow">LIFECYCLE</span><h2>Operational lifecycle</h2><p class="sub">Define the human-readable lifecycle first. Canonical states and transitions remain available in Advanced and are validated against the Action Registry.</p></div></div><div class="publisher-lifecycle-grid">${arr(sectors).map(sector=>{const d=life.find(x=>String(x.sectorCode||'')===String(sector));return `<article class="publisher-lifecycle-card"><div class="section-head"><div><b>${safe(labelSector(sector))}</b><div class="mini">${safe(d?.lifecycleKey||`${sector}.custom`)}</div></div>${present(d?.status||'missing')}</div><label class="field"><span>Lifecycle name</span><input class="input" data-life-name="${safe(sector)}" value="${safe(d?.name||`${labelSector(sector)} Lifecycle`)}"></label><label class="field"><span>Initial state</span><input class="input" data-life-initial="${safe(sector)}" value="${safe(d?.initialStateCode||'PENDING')}"></label><div class="publisher-stat-row"><div class="publisher-mini-stat"><span>States</span><strong>${safe(arr(d?.states).length)}</strong></div><div class="publisher-mini-stat"><span>Transitions</span><strong>${safe(arr(d?.transitions).length)}</strong></div></div><details class="publisher-advanced"><summary>ADVANCED · STATES & TRANSITIONS JSON</summary><label class="field"><span>Canonical states JSON</span><textarea class="input code-input" rows="8" data-life-states="${safe(sector)}">${escJson(arr(d?.states))}</textarea></label><label class="field"><span>Canonical transitions JSON</span><textarea class="input code-input" rows="10" data-life-transitions="${safe(sector)}">${escJson(arr(d?.transitions))}</textarea></label></details><div class="actions"><button class="btn primary" data-life-save="${safe(sector)}" data-life-id="${safe(d?.id||'')}" data-product-definition="${safe(d?.productDefinitionId||'')}">SAVE + VALIDATE</button></div></article>`}).join('')}</div></section>`;}
function releaseLifecycleSection(w){
 const r=w.releaseLifecycle||{};const history=arr(w.releaseHistory);const state=String(r.state||w.launch?.status||'draft').toUpperCase();
 const nextVersionAllowed=String(r.state||'')==='live'||w.launch?.active;
 const evidence=r.verificationEvidence||{};
 return `<section class="card section publisher-panel publisher-release-lifecycle-panel"><div class="section-head"><div><span class="eyebrow">RELEASE ENGINE</span><h2>Product release lifecycle</h2><p class="sub">The release record governs authorization, publication evidence, verification and rollback metadata without replacing the canonical product launch authority.</p></div><span class="pill ${['LIVE','VERIFIED','PUBLISHED','AUTHORIZED'].includes(state)?'ok':'warn'}">${safe(state)}</span></div><div class="publisher-release-state"><div class="publisher-release-state-track">${['DRAFT','VALIDATED','AUTHORIZED','PUBLISHED','VERIFIED','LIVE'].map((x,i)=>`<div class="publisher-release-state-node ${x===state?'current':''} ${['DRAFT','VALIDATED','AUTHORIZED','PUBLISHED','VERIFIED','LIVE'].indexOf(state)>=i?'reached':''}"><span>${i+1}</span><b>${x}</b></div>`).join('')}</div></div><div class="publisher-release-evidence-grid"><div><span>CONTRACT HASH</span><b title="${safe(r.contract_hash||'')}">${safe((r.contract_hash||'Not captured').slice(0,16))}${r.contract_hash?'…':''}</b></div><div><span>DEPENDENCY SNAPSHOT</span><b>${r.dependency_snapshot_json&&r.dependency_snapshot_json!=='{}'?'CAPTURED':'PENDING'}</b></div><div><span>VERIFICATION EVIDENCE</span><b>${Object.keys(evidence).length?'CAPTURED':'PENDING'}</b></div><div><span>ROLLBACK PATH</span><b>${r.rollback_path_json&&r.rollback_path_json!=='{}'?'DEFINED':'PENDING'}</b></div></div><div class="publisher-release-history"><div class="section-head"><div><b>RELEASE HISTORY</b><div class="mini">Every country version remains traceable; live versions are never edited in place.</div></div>${nextVersionAllowed?'<button class="btn primary" id="publisherNextVersion">CREATE NEXT VERSION</button>':''}</div>${history.map(x=>`<article class="publisher-release-history-row ${Number(x.launchId)===Number(w.launch?.id)?'current':''}"><div><b>v${safe(x.version)}</b><span class="pill ${String(x.state)==='live'?'ok':String(x.state)==='retired'?'muted':'warn'}">${safe(String(x.state||x.launch_status||'draft').toUpperCase())}</span></div><div class="mini">Launch #${safe(x.launchId)} · ${safe(x.launch_status||'—')} · ${x.effective_at?safe(x.effective_at):'not effective'}</div></article>`).join('')||'<div class="empty">No release history is available yet.</div>'}</div><details class="publisher-advanced"><summary>ROLLBACK / AUTHORIZATION DETAILS</summary><pre class="code-input">${escJson({previousLaunchId:r.previousLaunchId||null,authorization:r.authorization||null,rollbackPath:r.rollbackPath||{},verificationEvidence:evidence})}</pre></details></section>`;
}

function readinessSection(w){const read=w.readiness||{},release=w.releaseLifecycle||{},state=String(release.state||w.launch?.status||'draft');const validated=state==='validated',authorized=state==='authorized',active=Boolean(w.launch?.active);return `<section class="card section publisher-release-panel"><div class="publisher-review-grid"><div><div class="eyebrow">VALIDATION GATE</div><h2>Release readiness</h2><p class="sub">This score is explanatory. The server-side validation is authoritative and checks the exact country + product + launch version.</p><div class="publisher-stat-row"><div class="publisher-mini-stat"><span>Readiness</span><strong>${safe(read.score??0)}%</strong></div><div class="publisher-mini-stat"><span>Status</span><strong>${safe(read.valid?'READY':'BLOCKED')}</strong></div><div class="publisher-mini-stat"><span>Release</span><strong>${safe(state.toUpperCase())}</strong></div><div class="publisher-mini-stat"><span>Next</span><strong>${safe(w.next?.label||'—')}</strong></div></div>${arr(read.blockers).map(b=>`<div class="publisher-blocker"><span class="publisher-dot"></span><div><b>${safe(b.code)}</b><div class="mini">${safe(b.message)}</div></div></div>`).join('')||'<div class="notice"><b>No readiness blockers.</b> The product can proceed through the release gate.</div>'}</div><aside class="publisher-publish-card"><span class="eyebrow">RELEASE COMMANDS</span><h4>${safe(active?'LIVE PRODUCT':state==='authorized'?'AUTHORIZED RELEASE':state==='validated'?'VALIDATED RELEASE':'DRAFT PRODUCT')}</h4><p class="sub">Release actions are server-governed and step-up protected.</p><div class="publisher-release-actions"><button class="btn primary" id="publisherValidate" ${w.launch?.status==='draft'?'':'disabled'}>VALIDATE</button><button class="btn primary" id="publisherAuthorize" ${validated?'':'disabled'}>AUTHORIZE</button><button class="btn primary" id="publisherPublish" ${authorized?'':'disabled'}>PUBLISH</button><button class="btn primary" id="publisherVerify" ${active?'':'disabled'}>RUN LIVE VERIFICATION</button>${active?'<button class="btn danger" id="publisherRetire">DELIST / RETIRE</button>':''}</div></aside></div></section>`;}
function contractSection(w){const l=w.launch;return `<section class="card section publisher-panel publisher-preview-panel"><div class="section-head"><div><span class="eyebrow">PUBLISHED CONTRACT</span><h2>Canonical publication preview</h2><p class="sub">This preview is generated from the launch record. It is not a second editable copy.</p></div></div><div class="publisher-contract-grid"><div><span>Country</span><b>${safe(l.country_name||l.country_code)}</b></div><div><span>Version</span><b>${safe(l.version)}</b></div><div><span>Sectors</span><b>${arr(w.sectors).map(x=>safe(labelSector(x))).join(', ')}</b></div><div><span>State</span><b>${safe(l.status)}${l.active?' · LIVE':''}</b></div></div><pre>${escJson({countryCode:l.country_code,version:l.version,sectors:w.sectors,requiredConfigurations:l.manifest?.requiredConfigurations||[],eligibility:l.eligibility||{},launchMessage:l.manifest?.launchMessage||''})}</pre></section>`;}

function bind(box,{api,state,ensureStepUp,show,refresh}){
 box.querySelector('#clearCatalogContext')?.addEventListener('click',()=>{state.dataCatalogSelection=null;state.publisher={...(state.publisher||{}),countryCode:''};show('product-publisher')});
 const launch=state.publisher?.launchId;const msg=box.querySelector('#publisherScopeMsg');
 box.querySelector('#publisherStart')?.addEventListener('click',async()=>{const country=box.querySelector('#publisherCountry')?.value||'';const productName=box.querySelector('#publisherProductName')?.value.trim();const lang=box.querySelector('#publisherLanguage')?.value||'en';const message=box.querySelector('#publisherLaunchMessage')?.value.trim();const sectors=[...box.querySelectorAll('[data-sector-checkbox]:checked')].map(x=>x.value);if(!country||!productName||!sectors.length){msg.textContent='Country, product name and at least one sector are required.';return}if(!await ensureStepUp())return;msg.textContent=launch?'Saving scope…':'Starting product…';try{const selected=box.querySelector('#publisherCountry option:checked');if(!launch&&selected?.dataset.active!=='1'){msg.textContent='Product country is inactive. Activate it in Product Countries first.';return;}if(!launch){const r=await api('/api/platform/admin/product-publisher/start',{method:'POST',body:{countryCode:country,productName,primaryLanguageCode:lang,welcomeMessage:message,sectors}});await refresh({launchId:r.workspace?.launch?.id||null,countryCode:country});}else{await api(`/api/platform/admin/product-publisher/${launch}/scope`,{method:'POST',body:{productName,primaryLanguageCode:lang,launchMessage:message,welcomeMessage:message,sectors}});await refresh({launchId:launch,countryCode:country});}}catch(e){msg.textContent=e.message||'Scope operation failed.'}});
 box.querySelector('#publisherRefresh')?.addEventListener('click',()=>refresh({launchId:launch}));
 box.querySelector('#saveFoundation')?.addEventListener('click',async()=>{if(!launch||!await ensureStepUp())return;let invoice={};try{invoice=JSON.parse(box.querySelector('#foundationInvoice')?.value||'{}')}catch{alert('Invoice requirements JSON is invalid.');return}const retention={};box.querySelectorAll('[data-retention-days]').forEach(el=>{const p=el.dataset.retentionDays;retention[p]={retentionDays:Number(el.value),actionAfterExpiry:box.querySelector(`[data-retention-action="${p}"]`)?.value||'review',legalHoldAllowed:true}});try{await api(`/api/platform/admin/product-publisher/${launch}/foundation`,{method:'POST',body:{frameworkCode:box.querySelector('#foundationFramework')?.value.trim(),regionCode:box.querySelector('#foundationRegion')?.value.trim(),primaryRegion:box.querySelector('#foundationPrimaryRegion')?.value.trim(),primaryProvider:box.querySelector('#foundationStorageProvider')?.value||'',residencyMode:box.querySelector('#foundationResidencyMode')?.value||'required',currency:box.querySelector('#foundationCurrency')?.value.trim(),taxConfigurationCode:box.querySelector('#foundationTax')?.value.trim(),billingProviderCode:box.querySelector('#foundationBillingProvider')?.value||'stripe',invoiceRequirements:invoice,retention}});await refresh({launchId:launch})}catch(e){alert(e.message||'Country foundation failed')}});
 box.querySelectorAll('[data-legal-review]').forEach(b=>b.addEventListener('click',()=>{state.dataEntryType='policy';state.dataEntryContext={countryCode:state.publisher?.countryCode||'',launchId:launch,legalKey:b.dataset.legalKey,returnView:'product-publisher'};show('data-entry')}));
 box.querySelectorAll('[data-content-save]').forEach(b=>b.addEventListener('click',()=>{state.dataEntryType='page';state.dataEntryContext={countryCode:state.publisher?.countryCode||'',launchId:launch,contentKey:b.dataset.contentSave,returnView:'product-publisher'};show('data-entry')}));
 box.querySelectorAll('[data-task-complete]').forEach(b=>b.addEventListener('click',async()=>{if(!await ensureStepUp())return;const id=b.dataset.taskComplete;try{await api(`/api/platform/admin/product-preparation/tasks/${id}`,{method:'PATCH',body:{status:'completed',completionNote:box.querySelector(`[data-task-note="${id}"]`)?.value.trim()||'Completed in Product Publisher',evidence:{sources:(box.querySelector(`[data-task-sources="${id}"]`)?.value||'').split(',').map(x=>x.trim()).filter(Boolean)}}});await refresh({launchId:launch})}catch(e){alert(e.message||'Preparation update failed')}}));
 box.querySelectorAll('[data-research-complete]').forEach(b=>b.addEventListener('click',async()=>{if(!await ensureStepUp())return;const id=b.dataset.researchComplete;try{await api(`/api/platform/admin/product-preparation/research/${id}`,{method:'PATCH',body:{status:'completed',findings:box.querySelector(`[data-research-findings="${id}"]`)?.value.trim()||'Completed in Product Publisher',sources:(box.querySelector(`[data-research-sources="${id}"]`)?.value||'').split(',').map(x=>x.trim()).filter(Boolean)}});await refresh({launchId:launch})}catch(e){alert(e.message||'Research update failed')}}));
 box.querySelectorAll('[data-definition-save]').forEach(b=>b.addEventListener('click',async()=>{const id=Number(b.dataset.definitionSave);try{await ensureStepUp();await api(`/api/platform/admin/product-publisher/definitions/${id}`,{method:'POST',body:{launchId:launch,name:box.querySelector(`[data-definition-name="${id}"]`)?.value,description:box.querySelector(`[data-definition-description="${id}"]`)?.value}});await refresh({launchId:launch})}catch(e){alert(e.message||'Definition save failed')}}));
 box.querySelectorAll('[data-definition-compile]').forEach(b=>b.addEventListener('click',async()=>{try{await ensureStepUp();await api(`/api/platform/admin/product-definitions/${b.dataset.definitionCompile}/compile`,{method:'POST',body:{}});await refresh({launchId:launch})}catch(e){alert(e.message||'Definition compile failed')}}));
 box.querySelectorAll('[data-semantic-save]').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.semanticSave;const [domain,...rest]=key.split(':');state.dataEntryType='configuration';state.dataEntryContext={countryCode:state.publisher?.countryCode||'',launchId:launch,domainCode:domain,configKey:rest.join(':'),returnView:'product-publisher'};show('data-entry')}));
 box.querySelectorAll('[data-config-save]').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.configSave;const [domain,...rest]=key.split(':');state.dataEntryType='configuration';state.dataEntryContext={countryCode:state.publisher?.countryCode||'',launchId:launch,domainCode:domain,configKey:rest.join(':'),returnView:'product-publisher'};show('data-entry')}));
 box.querySelectorAll('[data-life-save]').forEach(b=>b.addEventListener('click',async()=>{const sector=b.dataset.lifeSave;try{const states=JSON.parse(box.querySelector(`[data-life-states="${sector}"]`)?.value||'[]');const transitions=JSON.parse(box.querySelector(`[data-life-transitions="${sector}"]`)?.value||'[]');if(!Array.isArray(states)||!Array.isArray(transitions))throw new Error('Lifecycle states and transitions must be arrays.');await ensureStepUp();await api(`/api/platform/admin/product-publisher/${launch}/lifecycle/${sector}`,{method:'POST',body:{lifecycleDefinitionId:b.dataset.lifeId?Number(b.dataset.lifeId):null,productDefinitionId:b.dataset.productDefinition?Number(b.dataset.productDefinition):null,name:box.querySelector(`[data-life-name="${sector}"]`)?.value||`${labelSector(sector)} Lifecycle`,initialStateCode:box.querySelector(`[data-life-initial="${sector}"]`)?.value||'PENDING',states,transitions,livenessPolicy:{terminalRequiresNoNextAction:true,nonTerminalRequiresNextActionOrWaiting:true}}});await refresh({launchId:launch})}catch(e){alert(e.message||'Lifecycle save failed')}}));
 box.querySelector('#publisherPrepareScenario')?.addEventListener('click',async()=>{if(!await ensureStepUp())return;const msg=box.querySelector('#publisherScenarioMsg');msg.textContent='Preparing controlled scenario…';try{const companyId=box.querySelector('#publisherScenarioCompany')?.value||'';const missionId=box.querySelector('#publisherScenarioMission')?.value||'';const sector=[...box.querySelectorAll('[data-sector-checkbox]:checked')].map(x=>x.value)[0]||'general';const r=await api('/api/platform/admin/product-publisher/test-lab/scenario',{method:'POST',body:{launchId:launch,companyId:companyId?Number(companyId):null,missionId:missionId?Number(missionId):null,sectorCode:sector}});msg.textContent=`Scenario ${String(r.scenario?.status||'prepared').toUpperCase()} · ${Number(r.scenario?.steps?.length||0)} controlled phases.`;await refresh({launchId:launch});}catch(e){msg.textContent=e.message||'Scenario preparation failed.'}});
 box.querySelector('#publisherValidate')?.addEventListener('click',async()=>{if(!await ensureStepUp())return;await perform('/validate','Product validation',{});});
 box.querySelector('#publisherAuthorize')?.addEventListener('click',async()=>{if(!await ensureStepUp())return;try{await api(`/api/platform/admin/country-product-launches/${launch}/authorize`,{method:'POST',body:{}});await refresh({launchId:launch,countryCode:state.publisher?.countryCode||''})}catch(e){alert(`Release authorization failed: ${e.message||'Unknown error'}`)}});
 box.querySelector('#publisherNextVersion')?.addEventListener('click',async()=>{if(!await ensureStepUp())return;try{const r=await api(`/api/platform/admin/country-product-launches/${launch}/next-version`,{method:'POST',body:{}});await refresh({launchId:r.draft?.id||null,countryCode:r.draft?.country_code||state.publisher?.countryCode||''})}catch(e){alert(`Next version creation failed: ${e.message||'Unknown error'}`)}});
 box.querySelector('#publisherPublish')?.addEventListener('click',async()=>{if(!await ensureStepUp())return;try{const current=await loadWorkspace(api,launch,state.publisher?.countryCode||'');const activeCountry=current.countries?.find(c=>String(c.code)===String(current.launch.country_code)&&Number(c.active)===1);await api(`/api/platform/admin/product-publisher/${launch}/publish`,{method:'POST',body:{expectedActiveLaunchId:current.activeLaunchId??null,expectedActiveVersion:activeCountry?.activeVersion??null}});await refresh({launchId:launch,countryCode:current.launch.country_code})}catch(e){alert(`Product publication failed: ${e.message||'Unknown error'}`)}});
 box.querySelector('#publisherVerify')?.addEventListener('click',async()=>{if(!await ensureStepUp())return;try{const current=await loadWorkspace(api,launch,state.publisher?.countryCode||'');const activeCountry=current.countries?.find(c=>String(c.code)===String(current.launch.country_code)&&Number(c.active)===1);const scenario=current.testScenario;const body=scenario?.id?{scenarioId:Number(scenario.id),countryCode:current.launch.country_code,sectorCode:scenario.sector_code||current.sectors?.[0]||'general',companyId:scenario.companyId||null,missionId:scenario.missionId||null,mode:'controlled',expectedActiveLaunchId:current.activeLaunchId??activeCountry?.activeLaunchId??current.launch.id,expectedActiveVersion:activeCountry?.activeVersion??current.launch.version}:{countryCode:current.launch.country_code,sectorCode:current.sectors?.[0]||'general',mode:'controlled',expectedActiveLaunchId:current.activeLaunchId??current.launch.id,expectedActiveVersion:activeCountry?.activeVersion??current.launch.version};await api(`/api/platform/admin/product-publisher/${launch}/verify`,{method:'POST',body});await refresh({launchId:launch,countryCode:current.launch.country_code})}catch(e){alert(`Live product verification failed: ${e.message||'Unknown error'}`)}});
 box.querySelectorAll('[data-factory-stage]').forEach(b=>b.addEventListener('click',()=>{const panel=box.querySelector(`[data-factory-panel="${b.dataset.factoryStage}"]`);if(panel){panel.open=true;panel.scrollIntoView({behavior:'smooth',block:'start'});}}));
 box.querySelectorAll('[data-factory-focus]').forEach(b=>b.addEventListener('click',()=>{const panel=box.querySelector(`[data-factory-panel="${b.dataset.factoryFocus}"]`);if(panel){panel.open=true;panel.scrollIntoView({behavior:'smooth',block:'start'});}}));
 box.querySelectorAll('[data-factory-toggle]').forEach(b=>b.addEventListener('click',()=>{const tool=box.querySelector(`[data-factory-tool="${b.dataset.factoryToggle}"]`);if(tool)tool.hidden=!tool.hidden;}));
 box.querySelectorAll('[data-factory-open]').forEach(b=>b.addEventListener('click',()=>show(b.dataset.factoryOpen==='inline-sector'?'countries':b.dataset.factoryOpen)));
 box.querySelectorAll('[data-factory-entry]').forEach(b=>b.addEventListener('click',()=>{state.dataEntryType=b.dataset.factoryEntry;state.dataEntryContext={countryCode:state.publisher?.countryCode||'',launchId:launch,definitionId:b.dataset.definitionId||null,returnView:'product-publisher'};show('data-entry')}));


 box.querySelector('#publisherRetire')?.addEventListener('click',async()=>{if(!launch||!await ensureStepUp())return;if(!confirm('Retire this live product version? A retired version is not edited or silently reused.'))return;try{await api(`/api/platform/admin/country-product-launches/${launch}/retire`,{method:'POST',body:{}});await refresh({launchId:launch})}catch(e){alert(`Product delist failed: ${e.message||'Unknown error'}`)}});
 async function perform(path,label,body){try{await api(`/api/platform/admin/product-publisher/${launch}${path}`,{method:'POST',body});await refresh({launchId:launch})}catch(e){alert(`${label} failed: ${e.message||'Unknown error'}`)}}
}

export async function renderProductPublisher(args){ if(args.state?.publisher?.legacy===true) return renderLegacyProductPublisher(args); return renderMarketFactory(args); }
